#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    const int max_threads = omp_get_max_threads();
    std::vector<long long> chunk_sums(max_threads, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t chunk_begin = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        const std::size_t chunk_end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        long long local_sum = 0;
        for (std::size_t i = chunk_begin; i < chunk_end; ++i) {
            local_sum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local_sum);
        }

        chunk_sums[tid] = local_sum;

        #pragma omp barrier

        long long offset = 0;
        for (int t = 0; t < tid; ++t) {
            offset += chunk_sums[t];
        }

        for (std::size_t i = chunk_begin; i < chunk_end; ++i) {
            output[i] = static_cast<int>(output[i] + offset);
        }
    }
}
